provenance.sourcePrompt:
Title lock-up overlay on a clean portrait photo — no text on the background image. 6s, 1920x1080, SILENT. Oxblood vertical line sweeps in from bottom, name reveals, subtitle fades. No corner brackets, no scan lines
```html
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<link href="https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700&family=Inter:wght@300;400&display=swap" rel="stylesheet">
<style>
root{--oxblood:#963f43;--ivory:#e7e0d4;--muted:#9b948a;}
*{margin:0;padding:0;box-sizing:border-box;}
body,#scene{width:1920px;height:1080px;overflow:hidden;background:#000;}
#scene{position:relative;}
/* background portrait — Ken Burns slow push */
#bg{
position:absolute;top:0;left:0;width:100%;height:100%
object-fit:cover;z-index:1
transform:scale(1.0);transform-origin:50% 42%
animation:kenburns 6s linear forwards
}
@keyframes kenburns{from{transform:scale(1.0)}to{transform:scale(1.06)}}
/* duotone: shadow → cool blue overlay */
#duo-blue{
position:absolute;top:0;left:0;width:100%;height:100%;z-index:2
background:#1a2a4a;mix-blend-mode:multiply;opacity:0.45
}
/* duotone: highlight → warm cream overlay */
#duo-warm{
position:absolute;top:0;left:0;width:100%;height:100%;z-index:3
background:#e8dcc8;mix-blend-mode:screen;opacity:0.16
}
/* dark gradient at bottom for text legibility */
#grad{
position:absolute;bottom:0;left:0;width:100%;height:55%;z-index:4
background:linear-gradient(to top,rgba(0,0,0,0.88) 0%,rgba(0,0,0,0.50) 55%,transparent 100%)
}
#lockup{
position:absolute;bottom:96px;left:96px;z-index:10
display:flex;flex-direction:row;align-items:flex-end;gap:24px
opacity:0
}
#vline{width:2px;height:0;background:var(--oxblood);flex-shrink:0;margin-bottom:4px;}
#text-col{display:flex;flex-direction:column;gap:6px;}
#name{
font-family:'Playfair Display',Georgia,serif
font-size:72px;font-weight:700
color:var(--ivory);letter-spacing:0.06em
line-height:1;opacity:0
}
#tagline{
font-family:'Inter',sans-serif
font-size:18px;font-weight:300
color:var(--muted);letter-spacing:0.32em;text-transform:uppercase
opacity:0
}
#meta{
font-family:'Inter',sans-serif
font-size:14px;font-weight:400
color:var(--oxblood);letter-spacing:0.28em;text-transform:uppercase
opacity:0;margin-top:2px
}
</style>
</head>
<body>
<div id="scene">
<img id="bg" src="{{bgImg}}" alt="">
<div id="duo-blue"></div>
<div id="duo-warm"></div>
<div id="grad"></div>
<div id="lockup">
<div id="vline"></div>
<div id="text-col">
<div id="name">BENEDICT CUMBERBATCH</div>
<div id="tagline">A STAR IN FOCUS</div>
<div id="meta">LONDON · 1976</div>
</div>
</div>
</div>
<script src="vendor/gsap.min.js"></script>
<script>
window.addEventListener('DOMContentLoaded',function(){
var tl=gsap.timeline()
tl.to('#lockup',{opacity:1,duration:0.01},0.6)
tl.to('#vline', {height:140,duration:0.7,ease:'expo.out'},0.6)
tl.to('#name',  {opacity:1,x:0,duration:0.7,ease:'power3.out',startAt:{opacity:0,x:-16}},0.95)
tl.to('#tagline',{opacity:1,duration:0.45,ease:'power2.out'},1.55)
tl.to('#meta',  {opacity:1,duration:0.45,ease:'power2.out'},1.85)
tl.to('#lockup',{opacity:0,duration:0.5,ease:'power2.in'},5.3)
})
</script>
</body>
</html>
```
